"use client"

import { useEffect, useState } from "react"
import { IconPlayerPause, IconPlayerPlay } from "@tabler/icons-react"
import { motion, useReducedMotion } from "motion/react"
import { Button } from "@/components/ui/button"

type Category = "furniture" | "lighting" | "textiles" | "tableware"
type RaceItem = { key: string; label: string; value: number; category: Category }
type RaceFrame = { period: string; values: readonly RaceItem[] }

const products = [
  ["Linen throw", "textiles"], ["Walnut sideboard", "furniture"], ["Mushroom lamp", "lighting"], ["Stoneware cups", "tableware"], ["Wool rug", "textiles"], ["Stacked bowls", "tableware"], ["Ceramic lamp", "lighting"], ["Oak lounge chair", "furniture"],
] as const
const values = [
  [178, 166, 154, 108, 84, 70, 48, 44], [184, 172, 160, 116, 91, 74, 52, 46], [218, 191, 181, 127, 100, 79, 57, 50], [194, 205, 188, 136, 104, 88, 62, 55], [202, 211, 196, 142, 111, 93, 67, 60], [210, 219, 202, 149, 117, 99, 72, 66], [220, 226, 210, 157, 124, 104, 78, 71], [229, 236, 218, 166, 131, 111, 84, 77], [238, 245, 227, 174, 138, 118, 91, 83], [247, 255, 236, 183, 146, 125, 98, 89], [258, 266, 245, 193, 155, 133, 105, 96], [270, 278, 256, 202, 164, 141, 113, 104],
] as const
const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"] as const
const categoryLabels: Record<Category, string> = { furniture: "Furniture", lighting: "Lighting", textiles: "Textiles", tableware: "Tableware" }
const categoryColors: Record<Category, string> = { furniture: "var(--chart-3)", lighting: "var(--chart-2)", textiles: "var(--chart-1)", tableware: "var(--chart-4)" }
const frames: readonly RaceFrame[] = values.map((frame, index) => ({ period: months[index] ?? "January", values: frame.map((value, itemIndex) => ({ key: products[itemIndex]?.[0].toLowerCase().replaceAll(" ", "-") ?? String(itemIndex), label: products[itemIndex]?.[0] ?? "Product", value: value * 1000, category: products[itemIndex]?.[1] ?? "furniture" })) }))

export function RaceBarChart() {
  const [frameIndex, setFrameIndex] = useState(2)
  const [playing, setPlaying] = useState(true)
  const [highlight, setHighlight] = useState<string | null>(null)
  const reducedMotion = useReducedMotion()
  const frame = frames[frameIndex] ?? frames[0]
  const total = frame.values.reduce((sum, item) => sum + item.value, 0)
  useEffect(() => {
    if (!playing || reducedMotion) return
    const timer = window.setInterval(() => setFrameIndex((current) => current >= frames.length - 1 ? 0 : current + 1), 1800)
    return () => window.clearInterval(timer)
  }, [playing, reducedMotion])
  function step(amount: number) { setFrameIndex((current) => Math.max(0, Math.min(frames.length - 1, current + amount))) }
  return <div className="grid w-full gap-5 rounded-[var(--radius)] border border-border bg-background p-6 sm:p-10">
    <div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="text-xl font-medium leading-tight sm:text-2xl sm:leading-8">Revenue by product</h2><p className="mt-1 text-base text-muted-foreground sm:text-lg sm:leading-7">Year to date, 2025</p></div><p className="text-base text-muted-foreground sm:text-lg">Total <span className="tabular-nums text-accent-strong">${(total / 1_000_000).toFixed(2)}M</span></p></div>
    <div className="grid gap-3"><h3 className="text-2xl font-normal leading-none text-accent-strong sm:text-4xl sm:leading-none">{frame.period}</h3><div className="ml-[9.5rem] flex justify-between text-xs tabular-nums text-muted-foreground sm:ml-[15rem] sm:text-sm">{[20, 40, 60, 80, 100, 120, 140, 160, 180, 200].map((tick) => <span key={tick}>${tick}K</span>)}</div><div className="relative grid gap-3 border-l border-border pl-0" role="group" tabIndex={0} aria-label={`${frame.period} revenue ranking. Use arrow keys to change month.`} onKeyDown={(event) => { if (event.key === "ArrowLeft") step(-1); if (event.key === "ArrowRight") step(1); if (event.key === "Home") setFrameIndex(0); if (event.key === "End") setFrameIndex(frames.length - 1); if (event.key === " ") { event.preventDefault(); setPlaying((current) => !current) } }}>
      <div className="pointer-events-none absolute inset-0 left-[9.5rem] grid grid-cols-10 sm:left-[15rem]">{Array.from({ length: 10 }, (_, index) => <span key={index} className="border-l border-border/60" />)}</div>
      {frame.values.map((item) => <motion.div layout key={item.key} className={`relative grid grid-cols-[9.5rem_minmax(0,1fr)_4.5rem] items-center gap-2 sm:grid-cols-[15rem_minmax(0,1fr)_5rem] sm:gap-3 ${highlight && highlight !== item.key ? "opacity-35" : ""}`} transition={{ duration: reducedMotion ? 0 : .55, ease: "easeOut" }} onMouseEnter={() => setHighlight(item.key)} onMouseLeave={() => setHighlight(null)}><span className={`truncate text-sm text-muted-foreground sm:text-base ${item.key === frame.values[frame.values.length - 1]?.key ? "font-medium text-foreground" : ""}`}>{item.label}</span><span className="h-8 overflow-hidden rounded-r-md bg-muted/40 sm:h-9"><motion.span layout className="block h-full rounded-r-md" style={{ backgroundColor: categoryColors[item.category] }} animate={{ width: `${Math.min(100, (item.value / 280_000) * 100)}%` }} transition={{ duration: reducedMotion ? 0 : .55, ease: "easeOut" }} /></span><motion.span key={`${item.key}-${frame.period}`} initial={reducedMotion ? false : { opacity: .4, y: 4 }} animate={reducedMotion ? undefined : { opacity: 1, y: 0 }} className="text-right text-sm tabular-nums sm:text-base">${Math.round(item.value / 1000)}K</motion.span></motion.div>)}
    </div></div>
    <div className="grid gap-5"><div className="flex flex-wrap items-center gap-5 text-base text-muted-foreground sm:text-lg">{(Object.keys(categoryLabels) as Category[]).map((category) => <span key={category} className="inline-flex items-center gap-2"><span className="size-3 rounded-sm" style={{ backgroundColor: categoryColors[category] }} />{categoryLabels[category]}</span>)}</div><div className="grid grid-cols-[3.5rem_minmax(0,1fr)] items-center gap-4"><Button type="button" size="icon-lg" variant="outline" className="rounded-full" aria-label={playing ? "Pause animation" : "Play animation"} aria-pressed={playing} onClick={() => setPlaying((current) => !current)}>{playing ? <IconPlayerPause /> : <IconPlayerPlay />}</Button><div className="grid gap-2"><input aria-label="Race bar month" type="range" min={0} max={frames.length - 1} value={frameIndex} onChange={(event) => setFrameIndex(Number(event.currentTarget.value))} className="h-2 w-full accent-muted-foreground" /><div className="flex justify-between text-base text-muted-foreground sm:text-lg"><span>January</span><span>December</span></div></div></div></div>
  </div>
}
